"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3171],{23331:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CombatService","desc":"Single server-side damage router. Resolves a hit (part or Model) to a\\ntarget and routes damage: a Player\'s character goes through `HealthManager`\\n(keeps the HUD-tracked record correct); a faction-tagged NPC (`EnemyNPC` /\\n`FriendlyNPC`, see Factions) with a Humanoid takes direct Humanoid damage.\\nAnything else is ignored. This is the ONLY place weapon code applies damage.\\n\\nNPC contract: a Model containing a Humanoid, tagged with EITHER the\\nCollectionService tag `\\"EnemyNPC\\"` or `\\"FriendlyNPC\\"` (see Factions). That\\nsame tag also places the NPC\'s parts in the `Character` collision group (see\\nNpcCollisionService), so thrown charges pass through it. Friendly-fire is\\nenforced here via Factions.canDamage: only Player<->Enemy damage lands, so\\nplayers never hurt players or friendly NPCs and enemies never hurt enemies or\\nfriendly NPCs. Self-damage from one\'s own AOE is exempt. A nil attacker is\\ntreated as environmental and bypasses the faction gate. Enemy AI/spawning is\\nsupplied elsewhere; this module only deals damage.","realm":["Server"],"source":{"line":22,"path":"src/ServerStorage/SharedModules/CombatService.luau"}}')}}]);